int LN,MN;long long GG[505][505];int MM[505][505];long long dfs2(int i,int j){if(MM[i][j])return MM[i][j];long long best=1;int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};for(int d=0;d<4;d++){int x=i+dx[d],y=j+dy[d];if(x>=0&&y>=0&&x<LN&&y<MN&&GG[x][y]>GG[i][j]){long long t=1+dfs2(x,y);if(t>best)best=t;}}MM[i][j]=(int)best;return best;}int main(){int n,m;cin>>n>>m;vector<vector<long long>>g(n,vector<long long>(m));for(auto&r:g)for(auto&x:r)cin>>x;LN=n;MN=m;for(int r2=0;r2<n;r2++)for(int c2=0;c2<m;c2++){GG[r2][c2]=g[r2][c2];MM[r2][c2]=0;}long long ans=0;for(int r2=0;r2<n;r2++)for(int c2=0;c2<m;c2++){long long v=dfs2(r2,c2);if(v>ans)ans=v;}cout<<ans<<"\n";return 0;}

