#include <string.h>
static int LN,MN;static long long GG[505][505];static int MM[505][505];static long long dfs2(int i,int j){if(MM[i][j])return MM[i][j];long long best=1;int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};int d;for(d=0;d<4;d++){int x=i+dx[d],y=j+dy[d];if(x>=0&&y>=0&&x<LN&&y<MN&&GG[x][y]>GG[i][j]){long long t=1+dfs2(x,y);if(t>best)best=t;}}MM[i][j]=(int)best;return best;}int main(void){int n,m,i,z;static long long g[505][505];if(scanf("%d %d",&n,&m)!=2)return 1;for(i=0;i<n;i++)for(z=0;z<m;z++)scanf("%lld",&g[i][z]);LN=n;MN=m;int r2,c2;for(r2=0;r2<n;r2++)for(c2=0;c2<m;c2++){GG[r2][c2]=g[r2][c2];MM[r2][c2]=0;}long long ans=0;for(r2=0;r2<n;r2++)for(c2=0;c2<m;c2++){long long v=dfs2(r2,c2);if(v>ans)ans=v;}printf("%lld\n",ans);return 0;}
